import React from 'https://cdn.jsdelivr.net/npm/react@18.2.0/+esm';
import reactDom from 'https://cdn.jsdelivr.net/npm/react-dom@18.2.0/+esm';
import * as XLSX from 'https://cdn.jsdelivr.net/npm/xlsx@0.18.5/+esm';

const e = React.createElement;

function downloadCSV(title, columns, rows) {
  const head = columns.join(",");
  const lines = rows.map(r => columns.map(c => '"' + (r[c] ?? "") + '"').join(","));
  const csv = [head, ...lines].join("\n");
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = title.toLowerCase() + "_stats.csv";
  a.click();
  URL.revokeObjectURL(url);
}

function downloadXLSX(title, columns, rows) {
  const sheetData = [columns, ...rows.map(r => columns.map(c => r[c] ?? ""))];
  const wb = XLSX.utils.book_new();
  const ws = XLSX.utils.aoa_to_sheet(sheetData);
  ws["!cols"] = [{ wch: 28 }, ...columns.slice(1).map(() => ({ wch: 14 }))];
  XLSX.utils.book_append_sheet(wb, ws, title + " Stats");
  XLSX.writeFile(wb, title.toLowerCase() + "_stats.xlsx");
}

function Section({ title, accent, rows, clickableMetric, onCellClick }) {
  if (!rows || rows.length === 0) return null;
  const columns = Object.keys(rows[0]);

  return e("div", { className: "section" },
    e("div", { className: "header", style: { borderLeft: "4px solid " + accent } },
      e("div", { className: "title" }, title),
      e("div", { className: "actions" },
        e("button", { className: "btn csv", onClick: () => downloadCSV(title, columns, rows) }, "\u2193 CSV"),
        e("button", { className: "btn xl", onClick: () => downloadXLSX(title, columns, rows) }, "\u2913 XLSX")
      )
    ),
    e("div", { className: "table-wrapper" },
      e("table", null,
        e("thead", null,
          e("tr", null, columns.map((c, i) => e("th", { key: c, className: i === 0 ? "sticky-col" : "" }, c)))
        ),
        e("tbody", null, rows.map((row, ri) =>
          e("tr", { key: ri }, columns.map((c, i) => {
            const val = row[c] ?? "";
            const isClickable = i !== 0 && clickableMetric && row.Metric === clickableMetric && onCellClick && Number(val) > 0;
            return e("td", {
              key: c,
              className: (i === 0 ? "sticky-col metric-col" : "") + (isClickable ? " clickable-count" : ""),
              onClick: isClickable ? () => onCellClick(c) : undefined
            }, typeof val === "number" ? val.toFixed(2) : val);
          }))
        ))
      )
    )
  );
}

function App() {
  const model = appsmith.model || {};
  const mis = model.mis || [];
  const qc = model.qc || [];
  const ai = model.ai || [];

  if (!mis.length && !qc.length && !ai.length) {
    return e("div", { className: "empty" }, "No data found.");
  }

  const handleQcFailedClick = (month) => {
    appsmith.updateModel({ qcFailedClick: { month } });
    appsmith.triggerEvent("onQcFailedClick");
  };

  return e("div", { className: "app" },
    e(Section, { title: "MIS", accent: "#2b62c0", rows: mis }),
    e(Section, {
      title: "QC", accent: "#d4732c", rows: qc,
      clickableMetric: "QC Failed", onCellClick: handleQcFailedClick
    }),
    e(Section, { title: "AI", accent: "#7a5cff", rows: ai })
  );
}

appsmith.onReady(() => {
  reactDom.render(e(App, null), document.getElementById("root"));
});

